const t = $('Lire ticket').first().json;
const MIN = Number($env.SIMILARITY_MIN || 0.5);
const errors = [];
const emb = $('Ollama · embedding').first().json;
if (emb.error) errors.push('embedding : ' + (emb.error.message || JSON.stringify(emb.error)));
const rows = $input.all().map(i => i.json).filter(r => r.content);
if (!rows.length && $input.first().json.error) errors.push('recherche : ' + JSON.stringify($input.first().json.error));
const kept = rows.filter(r => Number(r.similarity) >= MIN);
const sources = kept.map((r, i) => ({ n: i + 1, title: r.doc_title, section: r.section, path: r.doc_path,
                                      similarity: Number(r.similarity) }));
const context = kept.map((r, i) => `[${i + 1}] ${r.content}`).join('\n\n');
const system = [
  "Tu es l'assistant du support d'un intégrateur Odoo. Tu rédiges une réponse au client en français, claire et concise (150 mots maximum, étapes numérotées si utile).",
  "Tu t'appuies UNIQUEMENT sur les SOURCES fournies ; n'invente jamais de menu, de bouton ou de procédure.",
  "Cite les sources utilisées dans le texte avec leur numéro entre crochets, par exemple [1].",
  "sources_used = liste des numéros de sources réellement utilisées.",
  "Si les sources ne permettent pas de répondre à la demande, mets answerable = false et écris dans answer une phrase indiquant que la demande est transmise à un conseiller.",
  "Ne mets pas de formule de politesse finale ni de signature.",
].join('\n');
const user = `DEMANDE DU CLIENT\nSujet : ${t.subject || '(aucun)'}\n${t.body}\n\nSOURCES\n${context}`;
return [{ json: {
  ticket_id: Number(t.id), sources, has_sources: kept.length > 0,
  best_similarity: rows.length ? Math.max(...rows.map(r => Number(r.similarity))) : null,
  error: errors.join(' | ') || null,
  request: {
    stream: false, options: { temperature: 0.2, num_ctx: 8192 },
    format: { type: 'object', properties: {
      answer: { type: 'string' }, sources_used: { type: 'array', items: { type: 'integer' } }, answerable: { type: 'boolean' },
    }, required: ['answer', 'sources_used', 'answerable'] },
    messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  },
} }];

const p = $('Prompt RAG').first().json;
let r = {}, error = p.error;
try {
  if ($json.error) throw new Error(typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error));
  r = JSON.parse($json.message?.content || '');
} catch (e) { error = [error, 'réponse : ' + e.message].filter(Boolean).join(' | '); }
const answer = String(r.answer || '').trim();
const used = [...new Set((r.sources_used || []).map(Number))];
// Sources réellement citées (numéros valides, ou [n] présents dans le texte)
let cited = p.sources.filter(s => used.includes(s.n) || answer.includes(`[${s.n}]`));
if (!cited.length && r.answerable) cited = p.sources.slice(0, 1);
return [{ json: { ticket_id: p.ticket_id, answer: answer || null, answerable: r.answerable === true && !!answer,
                  sources: cited, error } }];

const p = $json;
return [{ json: { ticket_id: p.ticket_id, answer: null, answerable: false, sources: [],
                  error: p.error || null, best_similarity: p.best_similarity } }];
